/// Look up a swatch index by exact texture filename.
/// Uses a linear scan of the 1264-entry TILE_TABLE.
pub fn swatch_by_filename(name: &str) -> Option<usize> {
    TILE_TABLE.iter().position(|&(_, _, n)| n == name)
}

/// Get UV coordinates for a swatch: [u0, v0, u1, v1] in atlas space.
/// terrainExt.png is 256 wide × 1264 tall, with 16×16 tiles.
/// u = col/16, v = row*16/1264
pub fn swatch_uv(swatch: usize) -> Option<[f32; 4]> {
    let (col, row, _) = TILE_TABLE.get(swatch)?;
    let u0 = *col as f32 / 16.0;
    let v0 = *row as f32 * 16.0 / 1264.0;
    let u1 = (*col + 1) as f32 / 16.0;
    let v1 = (*row + 1) as f32 * 16.0 / 1264.0;
    Some([u0, v0, u1, v1])
}

/// The 6 face directions in order: top, bottom, east, west, south, north.
pub const FACE_NAMES: [&str; 6] = ["top", "bottom", "east", "west", "south", "north"];
